def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The patterned area follows a five-cell cycle. Determine each row's
    # cycle from its intact cells, favoring the long regular portion.
    for r in range(h):
        known = [c for c in range(3, w) if g[r][c] != 0]
        best = None
        for p in range(1, 11):
            votes = {}
            for c in known:
                votes.setdefault(c % p, {})
                v = g[r][c]
                votes[c % p][v] = votes[c % p].get(v, 0) + 1
            score = sum(max(d.values()) for d in votes.values())
            if best is None or score > best[0]:
                best = (score, p, votes)
        _, p, votes = best
        pattern = {k: max(d, key=d.get) for k, d in votes.items()}
        for c in range(3, w):
            if g[r][c] == 0 and c % p in pattern:
                g[r][c] = pattern[c % p]

    # Restore the simple outer frame where it was erased.
    for r in range(h):
        for c in range(min(3, w)):
            if g[r][c] == 0:
                g[r][c] = 1 if c < 2 else 4
    for r in range(h):
        for c in range(3, w):
            if g[r][c] == 0:
                g[r][c] = 4 if r == 2 else 1
    return g
